    try:
        payload = request.get_json()
        tasks = payload['tasks']
    except Exception as e:
        return jsonify({'error': 'Invalid payload', 'details': str(e)}), 422

    if not isinstance(tasks, list):
        return jsonify({'error': 'tasks must be a list'}), 422

    sorted_tasks = sorted(tasks)
    return jsonify({'sorted_tasks': sorted_tasks})

