from flask import Flask, request, jsonify
from datetime import datetime
import uuid

app = Flask(__name__)

@app.route('/reservations', methods=['POST'])
def create_reservation():
    data = request.get_json()

    if not data.get('guest_name') or not data.get('check_in') or not data.get('check_out'):
        return jsonify({'error': 'Missing required fields'}), 400

    try:
        check_in = datetime.fromisoformat(data['check_in'])
        check_out = datetime.fromisoformat(data['check_out'])
    except ValueError:
        return jsonify({'error': 'Invalid date format'}), 400

    if check_out <= check_in:
        return jsonify({'error': 'check_out must be after check_in'}), 400

    reservation_id = str(uuid.uuid4())
    return jsonify({'status': 'confirmed', 'reservation_id': reservation_id}), 201

if __name__ == '__main__':
    app.run(debug=True)

